interface InputProps extends Omit<HTMLProps<HTMLInputElement>, 'ref'> {
  label?: string
  id: string
  className?: string
  labelClassName?: string
  required?: boolean
}

const Input = forwardRef<HTMLInputElement, InputProps>(
  ({ label, id, className, labelClassName, required, ...props }, ref) => {
    return (
      <div className="w-full">
        <label
          htmlFor={id}
          className={clsx('text-xl text-gray-600', labelClassName)}
        >
          {label}
          {required && (
            <span className="ml-1 text-purple-800" aria-hidden="true">
              *
            </span>
          )}
        </label>

        <input
          ref={ref}
          id={id}
          className={clsx('w-full pl-4 text-xl focus:outline-none', className)}
          {...props}
        />
      </div>
    )
  },
)

