import clsx from 'clsx'
import { InputHTMLAttributes } from 'react'

interface CheckedBoxProps {
  label: string
  checked: boolean
  id?: number | string
  onChange: (id?: number | string) => void
  wrapperClassName?: string
  checkboxClassName?: string
  labelClassName?: string
}

export const CheckedBox = ({
  checked,
  id,
  onChange,
  label,
  wrapperClassName = '',
  checkboxClassName = '',
  labelClassName = '',
  ...props
}: CheckedBoxProps & InputHTMLAttributes<HTMLInputElement>) => {
  return (
    <div className={clsx('flex items-center', wrapperClassName)}>
      <input
        type="checkbox"
        id={`checkbox-${id}`}
        checked={checked}
        onChange={() => onChange(id)}
        className={checkboxClassName}
        {...props}
      />
      <label htmlFor={`checkbox-${id}`} className={labelClassName}>
        {label}
      </label>
    </div>
  )
}

