import clsx from 'clsx'
import { HTMLProps } from 'react'

interface RadioProps extends HTMLProps<HTMLInputElement> {
  label?: string
  id: string
  disabled?: boolean
  type?: string
  className?: string
  labelClassName?: string
}
interface CircleProps {
  disabled?: boolean
}
const Circle = ({ disabled }: CircleProps) => {
  return (
    <span
      className={clsx(
        'pointer-events-none absolute left-2/4 top-2/4 -translate-x-2/4 -translate-y-2/4  opacity-0 transition-opacity peer-checked:opacity-100',
        disabled ? 'text-gray-400' : 'text-purple-800',
      )}
    >
      <svg
        xmlns="http://www.w3.org/2000/svg"
        className="h-4 w-4"
        viewBox="0 0 16 16"
        fill="currentColor"
      >
        <circle data-name="ellipse" cx="8" cy="8" r="8" />
      </svg>
    </span>
  )
}

export const Radio = ({
  label,
  id,
  disabled,
  className,
  labelClassName,
  ...props
}: RadioProps) => {
  return (
    <div className={clsx('inline-flex items-center', className)}>
      <div className="relative flex cursor-pointer items-center rounded-full p-3">
        <input
          type="radio"
          className={clsx(
            "before:content[''] peer relative h-8 w-8 cursor-pointer appearance-none rounded-full border text-purple-800 transition-all before:absolute before:left-2/4 before:top-2/4 before:block before:h-12 before:w-12 before:-translate-x-2/4 before:-translate-y-2/4 before:rounded-full before:opacity-0 before:transition-opacity hover:before:opacity-10",
            disabled
              ? 'checked:border-gray-400'
              : 'checked:border-purple-800 checked:before:bg-purple-800',
          )}
          id={id}
          {...props}
          disabled={disabled}
        />
        <Circle disabled={disabled} />
      </div>
      <label
        className={clsx(
          'mt-px cursor-pointer select-none text-lg font-light text-gray-700',
          labelClassName,
        )}
        htmlFor={id}
      >
        {label}
      </label>
    </div>
  )
}

